// Command app is the single binary for every service. The first argument
// picks the subcommand.
//
//	app api                        serve the HTTP API (ADMIN_TOKEN, LISTEN_ADDR)
//	app migrate                    apply database migrations
//	app seed [-users N] [-seed S] [-as-of now|RFC3339] [-reset]
//	                               load synthetic users and events
//
// All need DATABASE_URL. More subcommands (worker, mockprovider) are added as
// they are built.
package main

import (
	"context"
	"database/sql"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/httpapi"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/seed"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	log := slog.New(slog.NewJSONHandler(os.Stderr, nil))

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: app <api|migrate|seed> [flags]")
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "api":
		err = apiCmd(ctx, log)
	case "migrate":
		err = migrate(ctx)
	case "seed":
		err = seedCmd(ctx, log, os.Args[2:])
	default:
		err = fmt.Errorf("unknown subcommand %q", os.Args[1])
	}
	if err != nil {
		log.Error("failed", "subcommand", os.Args[1], "error", err)
		os.Exit(1)
	}
}

func databaseURL() (string, error) {
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		return "", errors.New("DATABASE_URL is not set")
	}
	return url, nil
}

func apiCmd(ctx context.Context, log *slog.Logger) error {
	cfg, err := httpapi.ConfigFromEnv(os.Getenv)
	if err != nil {
		return err // fail closed: no token, no explicit opt-out, no API
	}
	if cfg.AdminToken == "" {
		log.Warn("ALLOW_UNAUTHENTICATED=true: the API accepts requests without a token; local development only")
	}
	url, err := databaseURL()
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()
	schemas, err := schema.Load()
	if err != nil {
		return err
	}
	srv := &httpapi.Server{Config: cfg, Pool: pool, Schemas: schemas, Log: log}
	h, err := srv.Handler()
	if err != nil {
		return err
	}
	hs := &http.Server{
		Addr:              cfg.ListenAddr,
		Handler:           h,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	go func() {
		<-ctx.Done()
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = hs.Shutdown(shutdown)
	}()
	log.Info("api listening", "addr", cfg.ListenAddr, "auth_required", cfg.AdminToken != "")
	if err := hs.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

func migrate(ctx context.Context) error {
	url, err := databaseURL()
	if err != nil {
		return err
	}
	db, err := sql.Open("pgx", url)
	if err != nil {
		return err
	}
	defer db.Close()
	return store.Migrate(ctx, db)
}

func seedCmd(ctx context.Context, log *slog.Logger, args []string) error {
	fs := flag.NewFlagSet("seed", flag.ContinueOnError)
	users := fs.Int("users", 5000, "number of users")
	seedValue := fs.Int64("seed", 42, "random seed")
	asOfFlag := fs.String("as-of", "now", `time anchor: "now" or an RFC 3339 time`)
	reset := fs.Bool("reset", false, "delete users, events and all campaigns first, then reload")
	if err := fs.Parse(args); err != nil {
		return err
	}
	asOf := time.Now()
	if *asOfFlag != "now" {
		var err error
		if asOf, err = time.Parse(time.RFC3339Nano, *asOfFlag); err != nil {
			return fmt.Errorf("-as-of: %w", err)
		}
	}
	ds, err := seed.Generate(*seedValue, asOf, *users)
	if err != nil {
		return err
	}
	url, err := databaseURL()
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()
	loaded, err := seed.Load(ctx, pool, ds, *reset)
	if err != nil {
		return err
	}
	if !loaded {
		log.Info("seed skipped: users already present (use -reset to reload)")
		return nil
	}
	log.Info("seed loaded", "users", len(ds.Users), "events", len(ds.Events), "seed", ds.Seed, "as_of", ds.AsOf)
	return nil
}
// Package jobs holds the River job argument types, queue names and worker
// settings. It is the contract between the side that inserts jobs (api,
// fan-out) and the workers, so both can be built in parallel. Kinds and
// queue names are stored in river_job rows: never rename one.
package jobs

import (
	"log/slog"
	"time"

	"github.com/riverqueue/river"
)

// Queue names.
const (
	QueueGenerate = "generate"
	QueueFanout   = "fanout"
	QueueSMS      = "sms"
	QueueEmail    = "email"
)

// QueueWorkers is how many jobs each queue runs at once in one worker process.
var QueueWorkers = map[string]int{
	QueueGenerate: 2,
	QueueFanout:   1,
	QueueSMS:      20,
	QueueEmail:    20,
}

// Per-worker job timeouts.
const (
	GenerateTimeout = 6 * time.Minute
	SendTimeout     = 30 * time.Second
)

// RescueStuckJobsAfter must exceed every job timeout. Otherwise the rescuer
// starts a second copy of a job that is still running.
const RescueStuckJobsAfter = 10 * time.Minute

// GenerateArgs asks for one generation of a campaign at a given version. A
// job whose version no longer matches the campaign does nothing.
type GenerateArgs struct {
	CampaignID string `json:"campaign_id"`
	Version    int    `json:"version"`
}

func (GenerateArgs) Kind() string { return "generate" }

func (GenerateArgs) InsertOpts() river.InsertOpts {
	return river.InsertOpts{Queue: QueueGenerate, UniqueOpts: river.UniqueOpts{ByArgs: true}}
}

// FanoutArgs creates the messages and send jobs of an approved campaign.
type FanoutArgs struct {
	CampaignID string `json:"campaign_id"`
}

func (FanoutArgs) Kind() string { return "fanout" }

func (FanoutArgs) InsertOpts() river.InsertOpts {
	return river.InsertOpts{Queue: QueueFanout, UniqueOpts: river.UniqueOpts{ByArgs: true}}
}

// SendArgs sends one message. It has no default queue: the inserter sets
// Queue to the message's channel (QueueSMS or QueueEmail), so each channel
// has its own workers.
type SendArgs struct {
	MessageID string `json:"message_id"`
}

func (SendArgs) Kind() string { return "send" }

func (SendArgs) InsertOpts() river.InsertOpts {
	return river.InsertOpts{UniqueOpts: river.UniqueOpts{ByArgs: true}}
}

// ClientConfig is the River configuration of a worker process: every queue
// with its worker count, and the stuck-job rescue delay. Job timeouts are
// set per worker (GenerateTimeout, SendTimeout). An insert-only client (the
// api) needs no config beyond a driver.
func ClientConfig(workers *river.Workers, log *slog.Logger) *river.Config {
	queues := make(map[string]river.QueueConfig, len(QueueWorkers))
	for q, n := range QueueWorkers {
		queues[q] = river.QueueConfig{MaxWorkers: n}
	}
	return &river.Config{
		Queues:               queues,
		Workers:              workers,
		RescueStuckJobsAfter: RescueStuckJobsAfter,
		Logger:               log,
	}
}
// Package retry classifies the outcome of an HTTP call and computes backoff
// delays (rule 6). The LLM client and the provider client share it, so both
// retry the same failures the same way.
package retry

import (
	"context"
	"errors"
	"math/rand/v2"
	"net"
	"net/http"
	"strconv"
	"strings"
	"syscall"
	"time"
)

// Class is the outcome of one call. The names are the error_class labels in
// the database and in metrics.
type Class string

const (
	Success     Class = "success"
	Timeout     Class = "timeout"      // 408, client timeout, context deadline
	RateLimited Class = "rate_limited" // 429
	ServerError Class = "server_error" // 5xx, 529 included
	ConnRefused Class = "conn_refused" // nothing listening: the request never arrived
	ConnReset   Class = "conn_reset"   // the connection died: the request may have arrived
	ClientError Class = "client_error" // any other status: never retried
)

// Retryable reports whether a call with this outcome may be tried again.
// Timeouts and resets are ambiguous; retrying them is safe only because every
// retry carries the same idempotency key.
func (c Class) Retryable() bool {
	switch c {
	case Timeout, RateLimited, ServerError, ConnRefused, ConnReset:
		return true
	}
	return false
}

// MaxRetryAfter caps a server's Retry-After, so a hostile or broken value
// cannot park a job for hours.
const MaxRetryAfter = 60 * time.Second

// Result is a classified outcome. RetryAfter is set only for a 429 that
// carries a usable Retry-After header.
type Result struct {
	Class      Class
	RetryAfter time.Duration
}

// Classify classifies a response or a transport error. err wins over resp,
// so a body read error can be passed with a nil resp. now resolves a
// Retry-After given as an HTTP date.
func Classify(resp *http.Response, err error, now time.Time) Result {
	if err != nil {
		return Result{Class: classifyErr(err)}
	}
	switch s := resp.StatusCode; {
	case s >= 200 && s < 300:
		return Result{Class: Success}
	case s == http.StatusRequestTimeout:
		return Result{Class: Timeout}
	case s == http.StatusTooManyRequests:
		return Result{Class: RateLimited, RetryAfter: retryAfter(resp.Header.Get("Retry-After"), now)}
	case s >= 500:
		return Result{Class: ServerError}
	}
	return Result{Class: ClientError}
}

func classifyErr(err error) Class {
	var ne net.Error
	switch {
	case errors.Is(err, context.DeadlineExceeded), errors.As(err, &ne) && ne.Timeout():
		return Timeout
	case errors.Is(err, syscall.ECONNREFUSED):
		return ConnRefused
	}
	// ECONNRESET, EPIPE, EOF and unexpected EOF all mean the connection died
	// mid-call. Any other transport error is treated the same way: the
	// request may or may not have reached the server.
	return ConnReset
}

// retryAfter parses delay-seconds or an HTTP date, clamped to [0, cap].
// Anything unparsable is 0, so the caller falls back to its own backoff.
func retryAfter(v string, now time.Time) time.Duration {
	v = strings.TrimSpace(v)
	if v == "" {
		return 0
	}
	if isDigits(v) {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n > int64(MaxRetryAfter/time.Second) {
			return MaxRetryAfter // only a range error is possible here
		}
		return time.Duration(n) * time.Second
	}
	t, err := http.ParseTime(v)
	if err != nil {
		return 0
	}
	return min(max(t.Sub(now), 0), MaxRetryAfter)
}

func isDigits(s string) bool {
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// Backoff base and cap.
const (
	BaseDelay = time.Second
	MaxDelay  = 60 * time.Second
)

// Backoff returns the delay before retry number attempt (0 is the first
// retry): full jitter, uniform over [0, min(MaxDelay, BaseDelay * 2^attempt)].
// The random source is injected so tests can fix it.
func Backoff(attempt int, rng *rand.Rand) time.Duration {
	ceiling := MaxDelay
	if attempt < 6 { // 2^6 s already exceeds MaxDelay; larger shifts overflow
		ceiling = min(BaseDelay<<max(attempt, 0), MaxDelay)
	}
	return time.Duration(rng.Int64N(int64(ceiling) + 1))
}
