// Package campaign is the approval state machine (rule 7): the transition
// table, guarded transitions with an audit row each, and the validation of
// new campaigns and revisions. SQL lives in internal/store.
package campaign

import (
	"context"
	"errors"
	"fmt"
	"slices"

	"github.com/jackc/pgx/v5"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
)

// State is a campaign state. The names are the campaign_state domain in
// migration 00002.
type State string

const (
	Draft                 State = "draft"
	Generating            State = "generating"
	InReview              State = "in_review"
	GenerationFailed      State = "generation_failed"
	Approved              State = "approved"
	Sending               State = "sending"
	Completed             State = "completed"
	CompletedWithFailures State = "completed_with_failures"
	Rejected              State = "rejected"
	Cancelled             State = "cancelled"
)

// transitions is the whole state machine. A state that is not a key is
// terminal.
var transitions = map[State][]State{
	Draft:            {Generating},
	Generating:       {InReview, GenerationFailed, Cancelled},
	GenerationFailed: {Generating, Cancelled},
	InReview:         {InReview, Generating, Approved, Rejected, Cancelled},
	Approved:         {Sending, Cancelled},
	Sending:          {Completed, CompletedWithFailures, Cancelled},
}

// States returns every state.
func States() []State {
	return []State{Draft, Generating, InReview, GenerationFailed, Approved,
		Sending, Completed, CompletedWithFailures, Rejected, Cancelled}
}

// CanTransition reports whether the table allows from -> to.
func CanTransition(from, to State) bool {
	return slices.Contains(transitions[from], to)
}

var (
	// ErrInvalidTransition: the table does not allow the move.
	ErrInvalidTransition = errors.New("campaign: transition not allowed")
	// ErrConflict: the campaign is not in the expected state at the expected
	// version (someone else moved it first), or does not exist.
	ErrConflict = errors.New("campaign: state or version changed")
)

// Move is one requested transition. Version is the version the caller saw.
type Move struct {
	ID       string
	From, To State
	Version  int
	Actor    string
	Reason   string
}

// Transition applies m with a guarded update and writes its audit row, both
// in the caller's transaction, so callers can add their own writes
// atomically. On error the caller must roll back.
func Transition(ctx context.Context, tx pgx.Tx, m Move) error {
	if !CanTransition(m.From, m.To) {
		return fmt.Errorf("%w: %s -> %s", ErrInvalidTransition, m.From, m.To)
	}
	ok, err := store.UpdateCampaignState(ctx, tx, m.ID, string(m.From), string(m.To), m.Version)
	if err != nil {
		return err
	}
	if !ok {
		return fmt.Errorf("%w: expected %s at version %d", ErrConflict, m.From, m.Version)
	}
	return store.InsertCampaignEvent(ctx, tx, m.ID, string(m.From), string(m.To), m.Actor, m.Reason)
}
package campaign

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Beginner starts a transaction. *pgxpool.Pool satisfies it.
type Beginner interface {
	Begin(ctx context.Context) (pgx.Tx, error)
}

// ErrNotFound: the campaign does not exist.
var ErrNotFound = store.ErrNotFound

func inTx(ctx context.Context, db Beginner, fn func(pgx.Tx) error) error {
	tx, err := db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// Create stores a draft campaign and its first audit row.
func Create(ctx context.Context, db Beginner, n New, actor string) (store.Campaign, error) {
	var c store.Campaign
	err := inTx(ctx, db, func(tx pgx.Tx) error {
		var err error
		if c, err = store.CreateCampaign(ctx, tx, n.Brief, n.CampaignURL); err != nil {
			return err
		}
		return store.InsertCampaignEvent(ctx, tx, c.ID, "", string(Draft), actor, "created")
	})
	return c, err
}

// Reject moves a campaign in review to rejected.
func Reject(ctx context.Context, db Beginner, id string, version int, actor string) error {
	return inTx(ctx, db, func(tx pgx.Tx) error {
		if _, err := store.GetCampaign(ctx, tx, id); err != nil {
			return err
		}
		return Transition(ctx, tx, Move{ID: id, From: InReview, To: Rejected, Version: version, Actor: actor})
	})
}

// Cancel moves a campaign to cancelled from any state that allows it, and in
// the same transaction takes its queued messages out of the queue. A worker
// that already holds one of the other messages loses its guarded update.
func Cancel(ctx context.Context, db Beginner, id string, version int, actor string) error {
	return inTx(ctx, db, func(tx pgx.Tx) error {
		c, err := store.GetCampaign(ctx, tx, id)
		if err != nil {
			return err
		}
		// The state read here can be stale; the guarded update then loses.
		if err := Transition(ctx, tx, Move{ID: id, From: State(c.State), To: Cancelled, Version: version, Actor: actor}); err != nil {
			return err
		}
		_, err = store.SkipQueuedMessages(ctx, tx, id)
		return err
	})
}

// Edit is a human edit of a campaign in review.
type Edit struct {
	ID             string
	BaseRevisionID string // the revision the reviewer edited
	Version        int    // the campaign version the reviewer saw
	Revision       Revision
	Warnings       []validation.Issue
	Actor          string
	AsOf           time.Time // "now" for the audience count
}

// SaveEdit stores a validated human edit as a new revision (source human),
// counts its audience again and keeps the campaign in review. It conflicts
// when the campaign moved on or the base revision is no longer current.
func SaveEdit(ctx context.Context, db Beginner, e Edit) (store.Revision, error) {
	segmentJSON, err := json.Marshal(e.Revision.SegmentDoc)
	if err != nil {
		return store.Revision{}, err
	}
	warnings := e.Warnings
	if warnings == nil {
		warnings = []validation.Issue{}
	}
	warningsJSON, err := json.Marshal(warnings)
	if err != nil {
		return store.Revision{}, err
	}
	var rev store.Revision
	err = inTx(ctx, db, func(tx pgx.Tx) error {
		if _, err := store.GetCampaign(ctx, tx, e.ID); err != nil {
			return err
		}
		// The transition locks the row, so the base check below and the
		// revision number cannot race with another edit.
		if err := Transition(ctx, tx, Move{ID: e.ID, From: InReview, To: InReview, Version: e.Version, Actor: e.Actor, Reason: "edit"}); err != nil {
			return err
		}
		c, err := store.GetCampaign(ctx, tx, e.ID)
		if err != nil {
			return err
		}
		if c.CurrentRevisionID == nil || *c.CurrentRevisionID != e.BaseRevisionID {
			return fmt.Errorf("%w: revision %s is not the current one", ErrConflict, e.BaseRevisionID)
		}
		counts, err := segment.CountAudience(ctx, tx, e.Revision.Segment, e.AsOf)
		if err != nil {
			return err
		}
		rev, err = store.InsertRevision(ctx, tx, store.NewRevision{
			CampaignID:    e.ID,
			Source:        "human",
			Segment:       segmentJSON,
			SMSBody:       e.Revision.Content.SMSBody,
			EmailSubject:  e.Revision.Content.EmailSubject,
			EmailBody:     e.Revision.Content.EmailBody,
			Warnings:      warningsJSON,
			AudienceTotal: counts.Total,
			SMSEligible:   counts.SMSEligible,
			EmailEligible: counts.EmailEligible,
		})
		return err
	})
	return rev, err
}
package campaign

import (
	"fmt"
	"net/url"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/content"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Limits of a new campaign.
const (
	MaxBriefChars = 2000
	MaxURLChars   = 40 // matches the CHECK on campaigns.campaign_url
)

// Revision is a validated segment plus content. SegmentDoc is the rule as
// segment.Validate normalized it in place; it is what gets stored.
type Revision struct {
	Segment    segment.Rule
	SegmentDoc any
	Content    content.Content
}

// ValidateRevision checks a revision document (an LLM answer or a human
// edit). It checks the top-level keys itself and hands each part to its own
// validator, with paths prefixed /segment and /content. It does not run
// revision.schema.json first: that schema refs the segment schema, so upper
// case enums would fail before normalization, and every error would be
// reported twice.
func ValidateRevision(set *schema.Set, doc any) (Revision, validation.Result) {
	var res validation.Result
	m, ok := doc.(map[string]any)
	if !ok {
		res.Error("", validation.InvalidType, `expected an object: {"segment": {...}, "content": {...}}`)
		return Revision{}, res
	}
	for k := range m {
		if k != "segment" && k != "content" {
			res.Error("/"+k, validation.UnknownProperty, fmt.Sprintf("key %q is not allowed", k))
		}
	}
	var rev Revision
	if seg, ok := m["segment"]; ok {
		rule, r := segment.Validate(set, seg)
		merge(&res, r, "/segment")
		rev.Segment, rev.SegmentDoc = rule, seg
	} else {
		res.Error("/segment", validation.Required, `missing required key "segment"`)
	}
	if c, ok := m["content"]; ok {
		cont, r := content.Validate(set, c)
		merge(&res, r, "/content")
		rev.Content = cont
	} else {
		res.Error("/content", validation.Required, `missing required key "content"`)
	}
	if !res.OK() {
		return Revision{}, res
	}
	return rev, res
}

func merge(dst *validation.Result, src validation.Result, prefix string) {
	for _, is := range src.Errors {
		dst.Error(prefix+is.Path, is.Code, is.Message)
	}
	for _, is := range src.Warnings {
		dst.Warn(prefix+is.Path, is.Code, is.Message)
	}
}

// New is a validated request to create a campaign.
type New struct {
	Brief       string
	CampaignURL string
}

// ValidateNew checks a create request: {"brief", "campaign_url"} and nothing
// else. The brief is 1 to MaxBriefChars characters. campaign_url is required,
// so {{campaign_url}} always has a target: https, on a host in hosts, with no
// user info or port, at most MaxURLChars characters.
func ValidateNew(doc any, hosts []string) (New, validation.Result) {
	var res validation.Result
	m, ok := doc.(map[string]any)
	if !ok {
		res.Error("", validation.InvalidType, `expected an object: {"brief": "...", "campaign_url": "..."}`)
		return New{}, res
	}
	for k := range m {
		if k != "brief" && k != "campaign_url" {
			res.Error("/"+k, validation.UnknownProperty, fmt.Sprintf("key %q is not allowed", k))
		}
	}
	var n New
	switch v, ok := m["brief"]; {
	case !ok:
		res.Error("/brief", validation.Required, `missing required key "brief"`)
	default:
		s, isString := v.(string)
		switch chars := utf8.RuneCountInString(s); {
		case !isString:
			res.Error("/brief", validation.InvalidType, "expected a string")
		case chars < 1:
			res.Error("/brief", validation.TooShort, "must be at least 1 character")
		case chars > MaxBriefChars:
			res.Error("/brief", validation.TooLong, fmt.Sprintf("must be at most %d characters, has %d", MaxBriefChars, chars))
		default:
			n.Brief = s
		}
	}
	switch v, ok := m["campaign_url"]; {
	case !ok:
		res.Error("/campaign_url", validation.Required, `missing required key "campaign_url"`)
	default:
		s, isString := v.(string)
		if !isString {
			res.Error("/campaign_url", validation.InvalidType, "expected a string")
			break
		}
		if chars := utf8.RuneCountInString(s); chars > MaxURLChars {
			res.Error("/campaign_url", validation.TooLong, fmt.Sprintf("must be at most %d characters, has %d", MaxURLChars, chars))
		}
		if !allowedURL(s, hosts) {
			res.Error("/campaign_url", validation.URLNotAllowed, "must be an https URL on an allowed host: "+strings.Join(hosts, ", "))
		}
		n.CampaignURL = s
	}
	if !res.OK() {
		return New{}, res
	}
	return n, res
}

func allowedURL(s string, hosts []string) bool {
	u, err := url.Parse(s)
	if err != nil || u.Scheme != "https" || u.User != nil || u.Opaque != "" {
		return false
	}
	// u.Host, not u.Hostname(): a port is not allowed either.
	return slices.Contains(hosts, strings.ToLower(u.Host))
}

