	template := os.Getenv("TEST_TEMPLATE_DB")
	if template == "" {
		template = "app_template"
	}
	u := create(t, template)

	db, err := sql.Open("pgx", u)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var s Seed
