		_, _ = conn.ExecContext(ctx, "SELECT pg_advisory_unlock($1)", cloneLock)
	}
	conn.Close()
	if createErr != nil {
		t.Fatalf("%s: %v (the template is built by make test)", stmt, createErr)
	}

