// Package content validates campaign copy: the SMS body and the email
// subject and body. Copy is plain text with {{ name }} variables from a fixed
// allowlist; links come only from {{campaign_url}}.
package content

import (
	"fmt"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// maxLen is the allowlist of template variables, with the most characters
// (runes) each may render to. The renderer truncates values to this length,
// so a worst-case length check made at validation time holds at send time.
// Nothing security-critical or contact-related (email, phone) is here.
var maxLen = map[string]int{
	"first_name":   20,
	"last_name":    20,
	"city":         15,
	"campaign_url": 40,
}

// mayBeNonGSM marks variables whose values can contain letters outside GSM-7,
// such as ş, ğ and ı in Turkish names and city names.
var mayBeNonGSM = map[string]bool{"first_name": true, "last_name": true, "city": true}

// Variables returns the allowlisted variable names, sorted.
func Variables() []string {
	names := make([]string, 0, len(maxLen))
	for n := range maxLen {
		names = append(names, n)
	}
	slices.Sort(names)
	return names
}

// Part is one piece of a parsed template: literal text, or one variable.
type Part struct {
	Text string // literal text, when Var is empty
	Var  string // variable name
}

// Parse splits a template into parts. Only {{ name }} with an allowlisted
// name is a variable. Unknown names, unclosed or stray braces, filters and
// nesting are errors. The returned issues have an empty Path; the caller
// knows which field it parsed.
func Parse(tmpl string) ([]Part, []validation.Issue) {
	var parts []Part
	var issues []validation.Issue
	var text strings.Builder
	flush := func() {
		if text.Len() > 0 {
			parts = append(parts, Part{Text: text.String()})
			text.Reset()
		}
	}
	at := func(i int) int { return utf8.RuneCountInString(tmpl[:i]) + 1 }

	for i := 0; i < len(tmpl); {
		switch {
		case strings.HasPrefix(tmpl[i:], "{{"):
			end := strings.Index(tmpl[i+2:], "}}")
			if end < 0 {
				issues = append(issues, validation.Issue{Code: validation.MalformedTemplate,
					Message: fmt.Sprintf("unclosed {{ at character %d", at(i))})
				text.WriteString(tmpl[i:])
				i = len(tmpl)
				continue
			}
			inner := tmpl[i+2 : i+2+end]
			name := strings.Trim(inner, " ")
			switch {
			case !isIdent(name):
				issues = append(issues, validation.Issue{Code: validation.MalformedTemplate,
					Message: fmt.Sprintf("{{%s}} at character %d is not a variable; write {{ name }} with no filters", inner, at(i))})
			case maxLen[name] == 0:
				issues = append(issues, validation.Issue{Code: validation.UnknownVariable,
					Message: fmt.Sprintf("{{%s}} is not an allowed variable; use one of: %s", name, strings.Join(Variables(), ", "))})
			default:
				flush()
				parts = append(parts, Part{Var: name})
			}
			i += 2 + end + 2
		case strings.HasPrefix(tmpl[i:], "}}"):
			issues = append(issues, validation.Issue{Code: validation.MalformedTemplate,
				Message: fmt.Sprintf("stray }} at character %d", at(i))})
			i += 2
		default:
			text.WriteByte(tmpl[i])
			i++
		}
	}
	flush()
	return parts, issues
}

func isIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		letter := r == '_' || ('a' <= r && r <= 'z') || ('A' <= r && r <= 'Z')
		if !letter && (i == 0 || r < '0' || r > '9') {
			return false
		}
	}
	return true
}

// worstCase renders parts with every variable at its maximum length. With
// turkish set, variables that may hold non-GSM letters are filled with ş.
func worstCase(parts []Part, turkish bool) string {
	var b strings.Builder
	for _, p := range parts {
		if p.Var == "" {
			b.WriteString(p.Text)
			continue
		}
		fill := "x"
		if turkish && mayBeNonGSM[p.Var] {
			fill = "ş"
		}
		b.WriteString(strings.Repeat(fill, maxLen[p.Var]))
	}
	return b.String()
}
package content

import (
	"bytes"
	"cmp"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Rendered length limits (runes, worst case). They match the maxLength of the
// raw templates in schemas/content.schema.json; content_test.go checks that.
const (
	SMSMaxChars     = 160
	SubjectMaxChars = 80
)

// Content is validated copy.
type Content struct {
	SMSBody      string
	EmailSubject string
	EmailBody    string
	// SMS is the pessimistic estimate: longest variable values, and Turkish
	// letters in names and city.
	SMS SMSInfo
}

// Banned patterns. They are checked on the text with every variable filled
// in by a placeholder, so "{{city}}.com" is caught too. {{campaign_url}} is
// the one allowed link and is filled with a space.
var (
	schemeRe = regexp.MustCompile(`(?i)[a-z][a-z0-9+.\-]*://|www\.`)
	// A bare domain: dot-separated labels ending in a common TLD. Labels are
	// Unicode-aware, so a Cyrillic lookalike such as "іnsider.com" is caught.
	domainRe = regexp.MustCompile(`(?i)(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+` +
		`(?:com|net|org|info|biz|io|co|ai|app|dev|me|ly|gl|to|cc|tv|xyz|link|shop|store|site|online|tr|eu|uk|de|us))(?:$|[^\p{L}\p{N}_-])`)
	// A domain with any TLD, given away by the path that follows it, such as
	// "evil.top/login". The TLD starts with a letter, so "10.30/11" passes.
	domainPathRe = regexp.MustCompile(`(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+\p{L}[\p{L}\p{N}-]+/)`)
	// What may touch {{campaign_url}}. Anything else could extend the link
	// into another one: "{{campaign_url}}@evil.top", "{{campaign_url}}.evil.com".
	// Before it: the start or white space, then opening punctuation.
	// After it: closing punctuation, then white space or the end.
	urlBeforeRe = regexp.MustCompile(`(?:^|[\s\p{Z}])[(\["'“‘«:]*$`)
	urlAfterRe  = regexp.MustCompile(`^[.,!?;:)\]"'”’»]*(?:[\s\p{Z}]|$)`)
	ipRe        = regexp.MustCompile(`(?:^|[^\p{N}.])(\d{1,3}(?:\.\d{1,3}){3})(?:$|[^\p{N}.])`)
	emailRe     = regexp.MustCompile(`[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+`)
	htmlRe      = regexp.MustCompile(`<\s*/?\s*[A-Za-z][^>]*>`)
)

// ValidateJSON parses and validates content given as raw JSON.
func ValidateJSON(set *schema.Set, data []byte) (Content, validation.Result) {
	doc, err := schema.Decode(bytes.NewReader(data))
	if err != nil {
		var res validation.Result
		res.Error("", validation.InvalidJSON, err.Error())
		return Content{}, res
	}
	return Validate(set, doc)
}

// Validate checks decoded content (from schema.Decode): the schema first,
// then templates, banned links, emails and HTML, and the worst-case rendered
// length. Every problem is reported. SMS encoding and segment count are
// warnings only.
func Validate(set *schema.Set, doc any) (Content, validation.Result) {
	var res validation.Result
	rawTooLong := map[string]bool{}
	if err := set.Validate(schema.Content, doc); err != nil {
		for _, is := range schema.Issues(err, "") {
			res.Errors = append(res.Errors, is)
			if is.Code == validation.TooLong {
				rawTooLong[is.Path] = true
			}
		}
	}

	fields := []struct {
		path, a, b string
		limit      int
	}{
		{"/sms/body", "sms", "body", SMSMaxChars},
		{"/email/subject", "email", "subject", SubjectMaxChars},
		{"/email/body", "email", "body", 0},
	}
	var smsParts []Part
	values := map[string]string{}
	for _, f := range fields {
		s, ok := lookup(doc, f.a, f.b)
		if !ok {
			continue // the schema already reported it
		}
		values[f.path] = s
		parts, issues := Parse(s)
		for _, is := range issues {
			res.Error(f.path, is.Code, is.Message)
		}
		checkBans(&res, f.path, parts)
		if len(issues) > 0 {
			continue // lengths of a broken template mean nothing
		}
		if f.limit > 0 && !rawTooLong[f.path] {
			if n := utf8.RuneCountInString(worstCase(parts, false)); n > f.limit {
				res.Error(f.path, validation.RenderedTooLong, fmt.Sprintf(
					"can render up to %d characters with the longest variable values; the limit is %d", n, f.limit))
			}
		}
		if f.path == "/sms/body" {
			smsParts = parts
		}
	}

	var info SMSInfo
	if smsParts != nil {
		info = MeasureSMS(worstCase(smsParts, true))
		if info.Segments > 1 {
			msg := fmt.Sprintf("%s, %d segments in the worst case", info.Encoding, info.Segments)
			if plain := MeasureSMS(worstCase(smsParts, false)); plain.Encoding != info.Encoding {
				msg += fmt.Sprintf(" (names or city may contain Turkish letters such as ş, ğ, ı that switch the SMS to UCS-2; without them: %s, %d segment(s))", plain.Encoding, plain.Segments)
			}
			res.Warn("/sms/body", validation.SMSMultiSegment, msg)
		}
	}

	slices.SortStableFunc(res.Errors, func(a, b validation.Issue) int { return cmp.Compare(a.Path, b.Path) })
	if !res.OK() {
		return Content{}, res
	}
	return Content{
		SMSBody:      values["/sms/body"],
		EmailSubject: values["/email/subject"],
		EmailBody:    values["/email/body"],
		SMS:          info,
	}, res
}

// checkBans reports links, email addresses and HTML in the literal text.
func checkBans(res *validation.Result, path string, parts []Part) {
	text := fill(parts)
	if urlTouched(parts) {
		res.Error(path, validation.URLNotAllowed, "text directly next to {{campaign_url}} is not allowed; put a space around it")
	} else if m := schemeRe.FindString(text); m != "" {
		res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m))
	} else if m := domainRe.FindStringSubmatch(text); m != nil {
		res.Error(path, validation.URLNotAllowed, fmt.Sprintf("domain %q is not allowed; use {{campaign_url}}", m[1]))
	} else if m := domainPathRe.FindStringSubmatch(text); m != nil {
		res.Error(path, validation.URLNotAllowed, fmt.Sprintf("link %q is not allowed; use {{campaign_url}}", m[1]))
	} else if m := ipRe.FindStringSubmatch(text); m != nil {
		res.Error(path, validation.URLNotAllowed, fmt.Sprintf("address %q is not allowed; use {{campaign_url}}", m[1]))
	}
	if m := emailRe.FindString(text); m != "" {
		res.Error(path, validation.EmailNotAllowed, fmt.Sprintf("email address %q is not allowed", m))
	}
	if m := htmlRe.FindString(text); m != "" {
		res.Error(path, validation.HTMLNotAllowed, fmt.Sprintf("HTML %q is not allowed; copy is plain text", m))
	}
}

// fill joins the parts with a placeholder for each variable: a space for
// {{campaign_url}}, an "x" for the others.
func fill(parts []Part) string {
	var b strings.Builder
	for _, p := range parts {
		switch p.Var {
		case "":
			b.WriteString(p.Text)
		case "campaign_url":
			b.WriteString(" ")
		default:
			b.WriteString("x")
		}
	}
	return b.String()
}

// urlTouched reports whether any {{campaign_url}} has text attached to it.
func urlTouched(parts []Part) bool {
	for i, p := range parts {
		if p.Var == "campaign_url" &&
			(!urlBeforeRe.MatchString(fill(parts[:i])) || !urlAfterRe.MatchString(fill(parts[i+1:]))) {
			return true
		}
	}
	return false
}

func lookup(doc any, a, b string) (string, bool) {
	m, _ := doc.(map[string]any)
	inner, _ := m[a].(map[string]any)
	s, ok := inner[b].(string)
	return s, ok
}
package content

import (
	"strings"
	"unicode/utf16"
)

// GSM 03.38 default alphabet (3GPP TS 23.038), without the escape code.
// The order follows the standard table, row by row.
const gsmBasic = "@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà"

// GSM 03.38 extension table. Each of these costs two septets (escape + char).
const gsmExtension = "\f^{}\\[~]|€"

// Segment sizes from the spec: a single SMS, and each part of a split SMS.
const (
	gsmSingle  = 160
	gsmPart    = 153
	ucs2Single = 70
	ucs2Part   = 67
)

// SMSInfo describes how an SMS body would be sent.
type SMSInfo struct {
	Encoding string `json:"encoding"` // "GSM-7" or "UCS-2"
	Units    int    `json:"units"`    // septets for GSM-7, UTF-16 code units for UCS-2
	Segments int    `json:"segments"`
}

// MeasureSMS picks the encoding and counts segments. One character outside
// GSM-7 switches the whole message to UCS-2. This is an estimate: real
// encoders never split an escape pair or a surrogate pair across parts,
// which can add a segment in rare cases.
func MeasureSMS(text string) SMSInfo {
	septets, gsm := 0, true
	for _, r := range text {
		switch {
		case strings.ContainsRune(gsmBasic, r):
			septets++
		case strings.ContainsRune(gsmExtension, r):
			septets += 2
		default:
			gsm = false
		}
	}
	if gsm {
		return SMSInfo{Encoding: "GSM-7", Units: septets, Segments: segments(septets, gsmSingle, gsmPart)}
	}
	units := len(utf16.Encode([]rune(text)))
	return SMSInfo{Encoding: "UCS-2", Units: units, Segments: segments(units, ucs2Single, ucs2Part)}
}

func segments(units, single, part int) int {
	if units <= single {
		return 1
	}
	return (units + part - 1) / part
}
// Package validation holds the result type every validator returns. The
// codes are stable: API clients, the LLM retry prompt and metric labels all
// depend on them, so add codes but never rename one.
package validation

// Codes for structural problems, mapped from JSON Schema keywords.
const (
	InvalidJSON     = "invalid_json"     // not exactly one JSON value
	Required        = "required"         // a required key is missing
	UnknownProperty = "unknown_property" // a key the schema does not define
	InvalidType     = "invalid_type"     // wrong JSON type
	UnknownValue    = "unknown_value"    // value outside an enum or const
	OutOfRange      = "out_of_range"     // number outside its minimum/maximum
	TooFew          = "too_few"          // array below minItems
	TooMany         = "too_many"         // array above maxItems
	DuplicateValue  = "duplicate_value"  // repeated array item
	TooShort        = "too_short"        // string below minLength
	TooLong         = "too_long"         // string above maxLength
	SchemaViolation = "schema_violation" // any other schema failure
)

// Codes for segment rules (docs/segment-rules.md).
const (
	OpNotAllowed    = "op_not_allowed"    // operator exists, but not for this field
	OpValueMismatch = "op_value_mismatch" // list operator with one value, or the reverse
)

// Codes for content (SMS and email templates).
const (
	UnknownVariable   = "unknown_variable"   // {{name}} outside the allowlist
	MalformedTemplate = "malformed_template" // broken braces, filters, nesting
	URLNotAllowed     = "url_not_allowed"    // links come only from {{campaign_url}}
	EmailNotAllowed   = "email_not_allowed"  // no email addresses in copy
	HTMLNotAllowed    = "html_not_allowed"   // copy is plain text
	RenderedTooLong   = "rendered_too_long"  // worst-case rendered text over the limit
)

// Warning codes. Warnings never block approval.
const (
	SMSMultiSegment = "sms_multi_segment" // the SMS may need more than one segment
)

// Issue is one problem. Path is a JSON Pointer into the validated document
// ("" is the document itself).
type Issue struct {
	Path    string `json:"path"`
	Code    string `json:"code"`
	Message string `json:"message"`
}

// Result collects every problem found, not just the first.
type Result struct {
	Errors   []Issue `json:"errors"`
	Warnings []Issue `json:"warnings"`
}

// OK reports whether there are no errors. Warnings do not count.
func (r Result) OK() bool { return len(r.Errors) == 0 }

// Error records an error.
func (r *Result) Error(path, code, message string) {
	r.Errors = append(r.Errors, Issue{Path: path, Code: code, Message: message})
}

// Warn records a warning.
func (r *Result) Warn(path, code, message string) {
	r.Warnings = append(r.Warnings, Issue{Path: path, Code: code, Message: message})
}
