		reply.StopReason = "end_turn"
	}
	model, _ := body["model"].(string)
	s.mu.Lock()
	s.seq++
	id := fmt.Sprintf("msg_mock_%06d", s.seq)
	s.mu.Unlock()
	in := len(raw)/4 + 1
	if stream, _ := body["stream"].(bool); stream {
		streamReply(w, r, id, model, in, reply)
