		for !p.done {
			p.ws()
			if p.peek(']') {
				p.i++
				return
			}
			p.skip()
			p.ws()
			switch {
			case p.peek(','):
				p.i++
			case p.peek(']'):
				p.i++
				return
			default:
				p.done = true
			}
		}
	default: // number, true, false, null
		for p.i < len(p.s) && strings.IndexByte(",}] \t\r\n", p.s[p.i]) < 0 {
			p.i++
		}
