type htmlPiece struct {
	Text string
	URL  string
}

var emailHTML = template.Must(template.New("email").Parse(`<!doctype html>
<html><body>
{{- range .}}
<p>{{range $i, $line := .}}{{if $i}}<br>{{end}}{{range $line}}{{if .URL}}<a href="{{.URL}}">{{.URL}}</a>{{else}}{{.Text}}{{end}}{{end}}{{end}}</p>
{{- end}}
</body></html>
`))

