// for the whole check and insert, so a concurrent request with the same key
// waits and then replays.
func (s *Server) process(ctx context.Context, key string, m message) (status int, id, outcome string, err error) {
	canon, _ := json.Marshal(m)
	sum := sha256.Sum256(canon)
	hash := hex.EncodeToString(sum[:])
