		t.Error("the X-Chaos hook is on without MOCKPROVIDER_CHAOS_HEADER=true")
	}
	for k, v := range map[string]string{
		"MOCKPROVIDER_RATE_500": "1.5", "MOCKPROVIDER_RATE_DROP": "x", "MOCKPROVIDER_LATENCY": "fast", "MOCKPROVIDER_SEED": "-1",
	} {
