package store

import (
	"database/sql"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// Migration 00004 adds messages.first_attempt_at. The send worker sets it
// once, on the first attempt, and declares a message dead 15 minutes later.
// It is empty until then, so it must be nullable.
func TestMessagesHaveFirstAttemptAt(t *testing.T) {
	url, _ := testdb.Seeded(t)
	db, err := sql.Open("pgx", url)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var typ, nullable string
	err = db.QueryRow(`SELECT data_type, is_nullable FROM information_schema.columns
		WHERE table_schema = 'public' AND table_name = 'messages' AND column_name = 'first_attempt_at'`).Scan(&typ, &nullable)
	if err == sql.ErrNoRows {
		t.Fatal("messages.first_attempt_at does not exist (migration 00004)")
	}
	if err != nil {
		t.Fatal(err)
	}
	if typ != "timestamp with time zone" || nullable != "YES" {
		t.Errorf("first_attempt_at is %s, nullable %s; want a nullable timestamptz", typ, nullable)
	}
	// A queued message that was never tried has no first attempt.
	var def sql.NullString
	if err := db.QueryRow(`SELECT column_default FROM information_schema.columns
		WHERE table_schema = 'public' AND table_name = 'messages' AND column_name = 'first_attempt_at'`).Scan(&def); err != nil {
		t.Fatal(err)
	}
	if def.Valid {
		t.Errorf("first_attempt_at has default %q; it must stay empty until the first attempt", def.String)
	}
}
	p, err := pgxpool.New(ctx, testdb.Fresh(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(p.Close)
	if err := mockprovider.Migrate(ctx, p); err != nil {
		t.Fatal(err)
	}
	cfg.ChaosHeader = true
	pr := &provider{inner: mockprovider.New(p, cfg), script: map[string][]string{}}
	pr.srv = httptest.NewServer(pr)
	t.Cleanup(pr.srv.Close)
	pr.URL = pr.srv.URL
	return pr
}

// force sets the X-Chaos of the next requests for key, in order. Requests
// past the script get no header ("" means the provider's own chaos).
func (p *provider) force(key string, chaos ...string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.script[key] = append(p.script[key], chaos...)
}

func (p *provider) hooks(onRequest, afterResponse func(key string)) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.onRequest, p.afterResponse = onRequest, afterResponse
}

func (p *provider) all() []call {
	p.mu.Lock()
	defer p.mu.Unlock()
	return append([]call(nil), p.calls...)
}

func (p *provider) callsFor(key string) []call {
	var out []call
	for _, c := range p.all() {
		if c.Key == key {
			out = append(out, c)
		}
	}
	return out
}

func (p *provider) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/v1/messages" {
		p.inner.ServeHTTP(w, r)
		return
	}
	body, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(body))
	key := r.Header.Get("Idempotency-Key")
	var decoded map[string]any
	_ = json.Unmarshal(body, &decoded)

	p.mu.Lock()
	chaos := ""
	if s := p.script[key]; len(s) > 0 {
		chaos, p.script[key] = s[0], s[1:]
	}
	i := len(p.calls)
	p.calls = append(p.calls, call{Key: key, Chaos: chaos, Body: decoded})
	before, after := p.onRequest, p.afterResponse
	p.mu.Unlock()

	r.Header.Del("X-Chaos") // only the test decides
	if chaos != "" {
		r.Header.Set("X-Chaos", chaos)
	}
	if before != nil {
		before(key)
	}
	rec := &statusRecorder{ResponseWriter: w}
	p.inner.ServeHTTP(rec, r)
	p.mu.Lock()
	p.calls[i].Status = rec.status
	p.mu.Unlock()
	if after != nil {
		after(key)
	}
}

func (p *provider) stats(t *testing.T) mockprovider.Stats {
	t.Helper()
	resp, err := p.srv.Client().Get(p.URL + "/v1/stats")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var s mockprovider.Stats
	if err := json.NewDecoder(resp.Body).Decode(&s); err != nil {
		t.Fatal(err)
	}
	return s
}

// statusRecorder notes the status and still lets the provider hijack the
// connection for the drop mode.
type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (r *statusRecorder) WriteHeader(code int) {
	if r.status == 0 {
		r.status = code
	}
	r.ResponseWriter.WriteHeader(code)
}

func (r *statusRecorder) Write(b []byte) (int, error) {
	if r.status == 0 {
		r.status = http.StatusOK
	}
	return r.ResponseWriter.Write(b)
}

func (r *statusRecorder) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	return http.NewResponseController(r.ResponseWriter).Hijack()
}

func (r *statusRecorder) Flush() { _ = http.NewResponseController(r.ResponseWriter).Flush() }

func (r *statusRecorder) Unwrap() http.ResponseWriter { return r.ResponseWriter }

